static boolean acquireInOrder(Lock first, Lock second, long timeoutMs) throws InterruptedException {
    if (!first.tryLock(timeoutMs, TimeUnit.MILLISECONDS)) return false;
    try {
        if (!second.tryLock(timeoutMs, TimeUnit.MILLISECONDS)) return false;
        try { System.out.println("obie zdobyte"); return true; } finally { second.unlock(); }
    } finally { first.unlock(); }
}
