static void withOrderedLocks(Object lockX, Object lockY, Runnable action) {
    Object first = System.identityHashCode(lockX) < System.identityHashCode(lockY) ? lockX : lockY;
    Object second = first == lockX ? lockY : lockX;
    synchronized (first) { synchronized (second) { action.run(); } }
}
