    Account z = konta[rnd.nextInt(5)], do_ = konta[rnd.nextInt(5)];
    if (z == do_) continue;
    pool.submit(() -> {
        Account pierwszy = z.id < do_.id ? z : do_, drugi = z.id < do_.id ? do_ : z;
        synchronized (pierwszy) { synchronized (drugi) { double kwota=10; z.saldo -= kwota; do_.saldo += kwota; } }
    });
}
pool.shutdown(); pool.awaitTermination(5, TimeUnit.SECONDS);
