class Publisher {
    private final List<Runnable> listenery = new ArrayList<>();
    private final Object lock = new Object();
    void subscribe(Runnable listener) { synchronized (lock) { listenery.add(listener); } }
    void publishNiebezpiecznie() { synchronized (lock) { for (Runnable l : listenery) l.run(); } } // callback WEWNATRZ synchronized - ryzykowne
    void publishBezpiecznie() { List<Runnable> kopia; synchronized (lock) { kopia = new ArrayList<>(listenery); } for (Runnable l : kopia) l.run(); } // callback POZA synchronized - bezpieczne
}
