static boolean isDeadlockSafe(Runnable scenario, long timeoutMs) throws InterruptedException {
    scenario.run();
    Thread.sleep(timeoutMs);
    return ManagementFactory.getThreadMXBean().findDeadlockedThreads() == null;
}
