static void safeAcquireHelper(List<Object> posortowane, int idx, Runnable action) {
    if (idx == posortowane.size()) { action.run(); return; }
    synchronized (posortowane.get(idx)) { safeAcquireHelper(posortowane, idx+1, action); }
}
static void safeAcquire(List<Object> resources, Runnable action) {
    List<Object> posortowane = new ArrayList<>(resources);
    posortowane.sort(Comparator.comparingInt(System::identityHashCode));
    safeAcquireHelper(posortowane, 0, action);
}
